_oldbind=socket.socket.bind
def _bind(self,address):
 result=_oldbind(self,address)
 if self.family in (socket.AF_INET,socket.AF_INET6):_ports.add(self.getsockname()[1])
 return result
socket.socket.bind=_bind
def _audit(event,args):
 if event in ("socket.connect","socket.sendto"):
  addr=args[1] if event=="socket.connect" else args[-1]
  if not isinstance(addr,tuple) or addr[0] not in ("localhost","127.0.0.1","::1") or addr[1] not in _ports:raise RuntimeError("Review network guard blocked destination")
 if event=="open":
  try:p=os.fspath(args[0])
  except TypeError:return
  if isinstance(p,str):
   p=os.path.abspath(p)
   if p.startswith(_home+"/.friday/") or p.startswith(_root+"/.friday/"):raise RuntimeError("Review store guard blocked real store")
